const test=require('node:test');
const assert=require('node:assert/strict');
const {leaders}=require('../scoreboard/service.cjs');
test('numeric ranks and eligibility',()=>{
  const rows=[{id:'a',score:'9',active:true},{id:'b',score:'80',active:true},{id:'c',score:'80.0',active:true},{id:'d',score:'0',active:true},{id:'e',score:'999',active:false},{id:'f',score:'100',active:'yes'}];
  const before=JSON.stringify(rows);
  const out=leaders(rows);
  assert.deepEqual(out.map(row=>[row.id,row.rank]),[['b',1],['c',1],['a',3],['d',4]]);
  assert.equal(JSON.stringify(rows),before);
  assert.notEqual(out[0],rows[1]);
  assert.deepEqual(leaders(rows,0),[]);
  assert.deepEqual(leaders(rows,2).map(row=>row.id),['b','c']);
  assert.equal(leaders(rows,null).length,4);
  assert.deepEqual(leaders([],4),[]);
  for(const bad of [-1,0.5]) assert.throws(()=>leaders(rows,bad),RangeError);
});

