exports.rank=function(records) {
  const sorted=records.slice().sort((a,b)=>Number(b.score)-Number(a.score));
  let position=0;
  return sorted.map((row,index)=>{
    if(index===0 || Number(row.score)!==Number(sorted[index-1].score)) position=index+1;
    return {...row,rank:position};
  });
};

