const {active}=require('./eligibility.cjs');
const {rank}=require('./rank.cjs');
exports.leaders=(records,limit)=>{
  if(limit!=null && (!Number.isInteger(limit)||limit<0)) throw new RangeError('invalid limit');
  const rows=rank(active(records));
  return limit==null ? rows : rows.slice(0,limit);
};

